command:
python3 -c 'import json,shutil,pathlib,os,hashlib,importlib.metadata as m,subprocess
out={"cli_path":shutil.which("vastai")}
gpu=subprocess.run(["nvidia-smi","--query-gpu=index,name,driver_version","--format=csv,noheader,nounits"],capture_output=True,text=True,timeout=10)
out["gpu"]={"exit_code":gpu.returncode,"stdout":gpu.stdout,"stderr":gpu.stderr}
try:
 d=m.distribution("vastai");out["package_version"]=d.version
 src=[d.locate_file(p) for p in (d.files or []) if str(p)=="vast.py"]
 out["source_sha256"]=hashlib.sha256(src[0].read_bytes()).hexdigest() if src else None
 out["credential_path_source_lines"]=[line for line in src[0].read_text().splitlines() if line.startswith("APIKEY_FILE") or "xdg_config_home()" in line] if src else []
except m.PackageNotFoundError:out["package_version"]=None
home=pathlib.Path.home(); config=pathlib.Path(os.environ.get("XDG_CONFIG_HOME",str(home/".config")))
for label,p in [("xdg_default",config/"vastai"/"vast_api_key"),("legacy_default",home/".vast_api_key")]:
 out[label]={"exists":p.is_file(),"readable":os.access(p,os.R_OK)}
out["key_values_read"]=False
print(json.dumps(out))'
